// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount, uint256 funding) public {
        funding = bound(funding, 1 ether, 1000 ether);
        vm.deal(address(c), funding);
        uint256 balBefore = address(c).balance;

        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The call succeeds iff the requested amount is affordable.
        assertTrue(ok == (amount <= balBefore));
    }
}
